// CAP DROIT — articles essentiels des codes et textes fondamentaux
// Texte officiel quand synth n'est pas indiqué ; synth = présentation synthétique d'un article long.
import type { Article, CodeId } from './types';

const A = (code: CodeId, num: string, titre: string, texte: string, synth?: boolean): Article => ({
  id: code + '-' + num.replace(/\s/g, ''),
  code,
  num,
  titre,
  texte,
  ...(synth ? { synth: true } : {}),
});

export const CODES: { id: CodeId; nom: string; court: string }[] = [
  { id: 'civ', nom: 'Code civil', court: 'C. civ.' },
  { id: 'pen', nom: 'Code pénal', court: 'C. pén.' },
  { id: 'cpp', nom: 'Code de procédure pénale', court: 'CPP' },
  { id: 'cpc', nom: 'Code de procédure civile', court: 'CPC' },
  { id: 'const', nom: 'Constitution du 4 octobre 1958', court: 'Const.' },
  { id: 'ddhc', nom: 'Déclaration des droits de l’homme et du citoyen de 1789', court: 'DDHC' },
  { id: 'cedh', nom: 'Convention européenne des droits de l’homme', court: 'Conv. EDH' },
  { id: 'trav', nom: 'Code du travail', court: 'C. trav.' },
  { id: 'cja', nom: 'Code de justice administrative', court: 'CJA' },
  { id: 'crpa', nom: 'Code des relations entre le public et l’administration', court: 'CRPA' },
  { id: 'com', nom: 'Code de commerce', court: 'C. com.' },
  { id: 'conso', nom: 'Code de la consommation', court: 'C. conso.' },
];

export const ARTICLES: Article[] = [
  // ===================== CODE CIVIL =====================
  A('civ', '1', 'Entrée en vigueur des lois', 'Les lois et, lorsqu’ils sont publiés au Journal officiel de la République française, les actes administratifs entrent en vigueur à la date qu’ils fixent ou, à défaut, le lendemain de leur publication. Toutefois, l’entrée en vigueur de celles de leurs dispositions dont l’exécution nécessite des mesures d’application est reportée à la date d’entrée en vigueur de ces mesures. (Les alinéas suivants prévoient une entrée en vigueur dès publication en cas d’urgence.)', true),
  A('civ', '2', 'Non-rétroactivité de la loi', 'La loi ne dispose que pour l’avenir ; elle n’a point d’effet rétroactif.'),
  A('civ', '4', 'Interdiction du déni de justice', 'Le juge qui refusera de juger, sous prétexte du silence, de l’obscurité ou de l’insuffisance de la loi, pourra être poursuivi comme coupable de déni de justice.'),
  A('civ', '5', 'Prohibition des arrêts de règlement', 'Il est défendu aux juges de prononcer par voie de disposition générale et réglementaire sur les causes qui leur sont soumises.'),
  A('civ', '6', 'Ordre public et bonnes mœurs', 'On ne peut déroger, par des conventions particulières, aux lois qui intéressent l’ordre public et les bonnes mœurs.'),
  A('civ', '9', 'Droit au respect de la vie privée', 'Chacun a droit au respect de sa vie privée. Les juges peuvent, sans préjudice de la réparation du dommage subi, prescrire toutes mesures, telles que séquestre, saisie et autres, propres à empêcher ou faire cesser une atteinte à l’intimité de la vie privée : ces mesures peuvent, s’il y a urgence, être ordonnées en référé.'),
  A('civ', '9-1', 'Présomption d’innocence', 'Chacun a droit au respect de la présomption d’innocence. Lorsqu’une personne est, avant toute condamnation, présentée publiquement comme étant coupable de faits faisant l’objet d’une enquête ou d’une instruction judiciaire, le juge peut, même en référé, ordonner toutes mesures (insertion d’une rectification, diffusion d’un communiqué) aux fins de faire cesser l’atteinte, sans préjudice d’une action en réparation.', true),
  A('civ', '16', 'Primauté de la personne et dignité', 'La loi assure la primauté de la personne, interdit toute atteinte à la dignité de celle-ci et garantit le respect de l’être humain dès le commencement de sa vie.'),
  A('civ', '16-1', 'Inviolabilité et non-patrimonialité du corps humain', 'Chacun a droit au respect de son corps. Le corps humain est inviolable. Le corps humain, ses éléments et ses produits ne peuvent faire l’objet d’un droit patrimonial.'),
  A('civ', '16-3', 'Atteinte à l’intégrité du corps et consentement', 'Il ne peut être porté atteinte à l’intégrité du corps humain qu’en cas de nécessité médicale pour la personne ou à titre exceptionnel dans l’intérêt thérapeutique d’autrui. Le consentement de l’intéressé doit être recueilli préalablement hors le cas où son état rend nécessaire une intervention thérapeutique à laquelle il n’est pas à même de consentir.'),
  A('civ', '16-7', 'Nullité de la gestation pour autrui', 'Toute convention portant sur la procréation ou la gestation pour le compte d’autrui est nulle.'),
  A('civ', '143', 'Mariage ouvert aux couples de même sexe', 'Le mariage est contracté par deux personnes de sexe différent ou de même sexe.'),
  A('civ', '144', 'Âge du mariage', 'Le mariage ne peut être contracté avant dix-huit ans révolus.'),
  A('civ', '146', 'Consentement au mariage', 'Il n’y a pas de mariage lorsqu’il n’y a point de consentement.'),
  A('civ', '212', 'Devoirs des époux', 'Les époux se doivent mutuellement respect, fidélité, secours, assistance.'),
  A('civ', '229', 'Cas de divorce', 'Les époux peuvent divorcer par consentement mutuel par acte sous signature privée contresigné par avocats et déposé au rang des minutes d’un notaire. Le divorce peut aussi être prononcé par le juge en cas de consentement mutuel judiciaire (notamment si un enfant demande à être entendu), d’acceptation du principe de la rupture du mariage, d’altération définitive du lien conjugal ou de faute.', true),
  A('civ', '371-1', 'Autorité parentale', 'L’autorité parentale est un ensemble de droits et de devoirs ayant pour finalité l’intérêt de l’enfant. Elle appartient aux parents jusqu’à la majorité ou l’émancipation de l’enfant pour le protéger dans sa sécurité, sa santé, sa vie privée et sa moralité, pour assurer son éducation et permettre son développement, dans le respect dû à sa personne. Elle s’exerce sans violences physiques ou psychologiques. Les parents associent l’enfant aux décisions qui le concernent, selon son âge et son degré de maturité.', true),
  A('civ', '414', 'Majorité et capacité', 'La majorité est fixée à dix-huit ans accomplis ; à cet âge, chacun est capable d’exercer les droits dont il a la jouissance.'),
  A('civ', '515-1', 'Définition du PACS', 'Un pacte civil de solidarité est un contrat conclu par deux personnes physiques majeures, de sexe différent ou de même sexe, pour organiser leur vie commune.'),
  A('civ', '515-8', 'Définition du concubinage', 'Le concubinage est une union de fait, caractérisée par une vie commune présentant un caractère de stabilité et de continuité, entre deux personnes, de sexe différent ou de même sexe, qui vivent en couple.'),
  A('civ', '516', 'Summa divisio des biens', 'Tous les biens sont meubles ou immeubles.'),
  A('civ', '544', 'Définition de la propriété', 'La propriété est le droit de jouir et disposer des choses de la manière la plus absolue, pourvu qu’on n’en fasse pas un usage prohibé par les lois ou par les règlements.'),
  A('civ', '545', 'Expropriation', 'Nul ne peut être contraint de céder sa propriété, si ce n’est pour cause d’utilité publique, et moyennant une juste et préalable indemnité.'),
  A('civ', '552', 'Propriété du dessus et du dessous', 'La propriété du sol emporte la propriété du dessus et du dessous. Le propriétaire peut faire au-dessus toutes les plantations et constructions qu’il juge à propos, sauf les exceptions établies au titre « Des servitudes ou services fonciers ». Il peut faire au-dessous toutes les constructions et fouilles qu’il jugera à propos, et tirer de ces fouilles tous les produits qu’elles peuvent fournir, sauf les modifications résultant des lois et règlements relatifs aux mines, et des lois et règlements de police.'),
  A('civ', '578', 'Définition de l’usufruit', 'L’usufruit est le droit de jouir des choses dont un autre a la propriété, comme le propriétaire lui-même, mais à la charge d’en conserver la substance.'),
  A('civ', '637', 'Définition de la servitude', 'Une servitude est une charge imposée sur un héritage pour l’usage et l’utilité d’un héritage appartenant à un autre propriétaire.'),
  A('civ', '815', 'Droit de sortir de l’indivision', 'Nul ne peut être contraint à demeurer dans l’indivision et le partage peut toujours être provoqué, à moins qu’il n’y ait été sursis par jugement ou convention.'),
  A('civ', '1100-1', 'Les actes juridiques', 'Les actes juridiques sont des manifestations de volonté destinées à produire des effets de droit. Ils peuvent être conventionnels ou unilatéraux. Ils obéissent, en tant que de raison, pour leur validité et leurs effets, aux règles qui gouvernent les contrats.'),
  A('civ', '1100-2', 'Les faits juridiques', 'Les faits juridiques sont des agissements ou des événements auxquels la loi attache des effets de droit. Les obligations qui naissent d’un fait juridique sont régies, selon le cas, par le sous-titre relatif à la responsabilité extracontractuelle ou le sous-titre relatif aux autres sources d’obligations.'),
  A('civ', '1101', 'Définition du contrat', 'Le contrat est un accord de volontés entre deux ou plusieurs personnes destiné à créer, modifier, transmettre ou éteindre des obligations.'),
  A('civ', '1102', 'Liberté contractuelle', 'Chacun est libre de contracter ou de ne pas contracter, de choisir son cocontractant et de déterminer le contenu et la forme du contrat dans les limites fixées par la loi. La liberté contractuelle ne permet pas de déroger aux règles qui intéressent l’ordre public.'),
  A('civ', '1103', 'Force obligatoire du contrat', 'Les contrats légalement formés tiennent lieu de loi à ceux qui les ont faits.'),
  A('civ', '1104', 'Bonne foi', 'Les contrats doivent être négociés, formés et exécutés de bonne foi. Cette disposition est d’ordre public.'),
  A('civ', '1110', 'Contrat de gré à gré et contrat d’adhésion', 'Le contrat de gré à gré est celui dont les stipulations sont négociables entre les parties. Le contrat d’adhésion est celui qui comporte un ensemble de clauses non négociables, déterminées à l’avance par l’une des parties.'),
  A('civ', '1112-1', 'Devoir précontractuel d’information', 'Celle des parties qui connaît une information dont l’importance est déterminante pour le consentement de l’autre doit l’en informer dès lors que, légitimement, cette dernière ignore cette information ou fait confiance à son cocontractant. Ce devoir ne porte pas sur l’estimation de la valeur de la prestation. Ont une importance déterminante les informations qui ont un lien direct et nécessaire avec le contenu du contrat ou la qualité des parties. Les parties ne peuvent ni limiter ni exclure ce devoir.', true),
  A('civ', '1113', 'Formation par offre et acceptation', 'Le contrat est formé par la rencontre d’une offre et d’une acceptation par lesquelles les parties manifestent leur volonté de s’engager. Cette volonté peut résulter d’une déclaration ou d’un comportement non équivoque de son auteur.'),
  A('civ', '1121', 'Moment et lieu de formation', 'Le contrat est conclu dès que l’acceptation parvient à l’offrant. Il est réputé l’être au lieu où l’acceptation est parvenue.'),
  A('civ', '1124', 'Promesse unilatérale', 'La promesse unilatérale est le contrat par lequel une partie, le promettant, accorde à l’autre, le bénéficiaire, le droit d’opter pour la conclusion d’un contrat dont les éléments essentiels sont déterminés, et pour la formation duquel ne manque que le consentement du bénéficiaire. La révocation de la promesse pendant le temps laissé au bénéficiaire pour opter n’empêche pas la formation du contrat promis. Le contrat conclu en violation de la promesse unilatérale avec un tiers qui en connaissait l’existence est nul.'),
  A('civ', '1128', 'Conditions de validité du contrat', 'Sont nécessaires à la validité d’un contrat : 1° Le consentement des parties ; 2° Leur capacité de contracter ; 3° Un contenu licite et certain.'),
  A('civ', '1130', 'Vices du consentement : caractère déterminant', 'L’erreur, le dol et la violence vicient le consentement lorsqu’ils sont de telle nature que, sans eux, l’une des parties n’aurait pas contracté ou aurait contracté à des conditions substantiellement différentes. Leur caractère déterminant s’apprécie eu égard aux personnes et aux circonstances dans lesquelles le consentement a été donné.'),
  A('civ', '1132', 'L’erreur', 'L’erreur de droit ou de fait, à moins qu’elle ne soit inexcusable, est une cause de nullité du contrat lorsqu’elle porte sur les qualités essentielles de la prestation due ou sur celles du cocontractant.'),
  A('civ', '1137', 'Le dol', 'Le dol est le fait pour un contractant d’obtenir le consentement de l’autre par des manœuvres ou des mensonges. Constitue également un dol la dissimulation intentionnelle par l’un des contractants d’une information dont il sait le caractère déterminant pour l’autre partie. Néanmoins, ne constitue pas un dol le fait pour une partie de ne pas révéler à son cocontractant son estimation de la valeur de la prestation.'),
  A('civ', '1140', 'La violence', 'Il y a violence lorsqu’une partie s’engage sous la pression d’une contrainte qui lui inspire la crainte d’exposer sa personne, sa fortune ou celles de ses proches à un mal considérable.'),
  A('civ', '1143', 'Abus de l’état de dépendance', 'Il y a également violence lorsqu’une partie, abusant de l’état de dépendance dans lequel se trouve son cocontractant à son égard, obtient de lui un engagement qu’il n’aurait pas souscrit en l’absence d’une telle contrainte et en tire un avantage manifestement excessif.'),
  A('civ', '1162', 'Contenu licite du contrat', 'Le contrat ne peut déroger à l’ordre public ni par ses stipulations, ni par son but, que ce dernier ait été connu ou non par toutes les parties.'),
  A('civ', '1170', 'Clause privant de sa substance l’obligation essentielle', 'Toute clause qui prive de sa substance l’obligation essentielle du débiteur est réputée non écrite.'),
  A('civ', '1171', 'Clauses abusives dans le contrat d’adhésion', 'Dans un contrat d’adhésion, toute clause non négociable, déterminée à l’avance par l’une des parties, qui crée un déséquilibre significatif entre les droits et obligations des parties au contrat est réputée non écrite. L’appréciation du déséquilibre significatif ne porte ni sur l’objet principal du contrat ni sur l’adéquation du prix à la prestation.'),
  A('civ', '1178', 'La nullité et ses effets', 'Un contrat qui ne remplit pas les conditions requises pour sa validité est nul. La nullité doit être prononcée par le juge, à moins que les parties ne la constatent d’un commun accord. Le contrat annulé est censé n’avoir jamais existé. Les prestations exécutées donnent lieu à restitution. Indépendamment de l’annulation du contrat, la partie lésée peut demander réparation du dommage subi dans les conditions du droit commun de la responsabilité extracontractuelle.', true),
  A('civ', '1179', 'Nullité absolue et nullité relative', 'La nullité est absolue lorsque la règle violée a pour objet la sauvegarde de l’intérêt général. Elle est relative lorsque la règle violée a pour seul objet la sauvegarde d’un intérêt privé.'),
  A('civ', '1188', 'Interprétation du contrat', 'Le contrat s’interprète d’après la commune intention des parties plutôt qu’en s’arrêtant au sens littéral de ses termes. Lorsque cette intention ne peut être décelée, le contrat s’interprète selon le sens que lui donnerait une personne raisonnable placée dans la même situation.'),
  A('civ', '1190', 'Interprétation en cas de doute', 'Dans le doute, le contrat de gré à gré s’interprète contre le créancier et en faveur du débiteur, et le contrat d’adhésion contre celui qui l’a proposé.'),
  A('civ', '1195', 'Imprévision', 'Si un changement de circonstances imprévisible lors de la conclusion du contrat rend l’exécution excessivement onéreuse pour une partie qui n’avait pas accepté d’en assumer le risque, celle-ci peut demander une renégociation du contrat à son cocontractant. Elle continue à exécuter ses obligations durant la renégociation. En cas de refus ou d’échec de la renégociation, les parties peuvent convenir de la résolution du contrat, à la date et aux conditions qu’elles déterminent, ou demander d’un commun accord au juge de procéder à son adaptation. A défaut d’accord dans un délai raisonnable, le juge peut, à la demande d’une partie, réviser le contrat ou y mettre fin, à la date et aux conditions qu’il fixe.'),
  A('civ', '1199', 'Effet relatif du contrat', 'Le contrat ne crée d’obligations qu’entre les parties. Les tiers ne peuvent ni demander l’exécution du contrat ni se voir contraints de l’exécuter, sous réserve des dispositions de la présente section et de celles du chapitre III du titre IV.'),
  A('civ', '1217', 'Sanctions de l’inexécution', 'La partie envers laquelle l’engagement n’a pas été exécuté, ou l’a été imparfaitement, peut : refuser d’exécuter ou suspendre l’exécution de sa propre obligation ; poursuivre l’exécution forcée en nature de l’obligation ; obtenir une réduction du prix ; provoquer la résolution du contrat ; demander réparation des conséquences de l’inexécution. Les sanctions qui ne sont pas incompatibles peuvent être cumulées ; des dommages et intérêts peuvent toujours s’y ajouter.'),
  A('civ', '1218', 'Force majeure contractuelle', 'Il y a force majeure en matière contractuelle lorsqu’un événement échappant au contrôle du débiteur, qui ne pouvait être raisonnablement prévu lors de la conclusion du contrat et dont les effets ne peuvent être évités par des mesures appropriées, empêche l’exécution de son obligation par le débiteur. Si l’empêchement est temporaire, l’exécution de l’obligation est suspendue, à moins que le retard qui en résulterait ne justifie la résolution du contrat. Si l’empêchement est définitif, le contrat est résolu de plein droit et les parties sont libérées de leurs obligations.', true),
  A('civ', '1219', 'Exception d’inexécution', 'Une partie peut refuser d’exécuter son obligation, alors même que celle-ci est exigible, si l’autre n’exécute pas la sienne et si cette inexécution est suffisamment grave.'),
  A('civ', '1221', 'Exécution forcée en nature', 'Le créancier d’une obligation peut, après mise en demeure, en poursuivre l’exécution en nature sauf si cette exécution est impossible ou s’il existe une disproportion manifeste entre son coût pour le débiteur de bonne foi et son intérêt pour le créancier.'),
  A('civ', '1224', 'Résolution du contrat', 'La résolution résulte soit de l’application d’une clause résolutoire soit, en cas d’inexécution suffisamment grave, d’une notification du créancier au débiteur ou d’une décision de justice.'),
  A('civ', '1231-1', 'Responsabilité contractuelle', 'Le débiteur est condamné, s’il y a lieu, au paiement de dommages et intérêts soit à raison de l’inexécution de l’obligation, soit à raison du retard dans l’exécution, s’il ne justifie pas que l’exécution a été empêchée par la force majeure.'),
  A('civ', '1231-3', 'Prévisibilité du dommage contractuel', 'Le débiteur n’est tenu que des dommages et intérêts qui ont été prévus ou qui pouvaient être prévus lors de la conclusion du contrat, sauf lorsque l’inexécution est due à une faute lourde ou dolosive.'),
  A('civ', '1231-5', 'Clause pénale', 'Lorsque le contrat stipule que celui qui manquera de l’exécuter paiera une certaine somme à titre de dommages et intérêts, il ne peut être alloué à l’autre partie une somme plus forte ni moindre. Néanmoins, le juge peut, même d’office, modérer ou augmenter la pénalité ainsi convenue si elle est manifestement excessive ou dérisoire. Toute stipulation contraire est réputée non écrite. Sauf inexécution définitive, la pénalité n’est encourue que lorsque le débiteur est mis en demeure.', true),
  A('civ', '1240', 'Responsabilité du fait personnel (faute)', 'Tout fait quelconque de l’homme, qui cause à autrui un dommage, oblige celui par la faute duquel il est arrivé à le réparer.'),
  A('civ', '1241', 'Faute de négligence ou d’imprudence', 'Chacun est responsable du dommage qu’il a causé non seulement par son fait, mais encore par sa négligence ou par son imprudence.'),
  A('civ', '1242', 'Responsabilité du fait d’autrui et du fait des choses', 'On est responsable non seulement du dommage que l’on cause par son propre fait, mais encore de celui qui est causé par le fait des personnes dont on doit répondre, ou des choses que l’on a sous sa garde. Les alinéas suivants visent notamment : les père et mère, solidairement responsables du dommage causé par leurs enfants mineurs habitant avec eux (al. 4) ; les maîtres et commettants, responsables du dommage causé par leurs domestiques et préposés dans les fonctions auxquelles ils les ont employés (al. 5) ; les instituteurs et artisans, sous condition de faute prouvée (al. 6 et 8).', true),
  A('civ', '1243', 'Responsabilité du fait des animaux', 'Le propriétaire d’un animal, ou celui qui s’en sert, pendant qu’il est à son usage, est responsable du dommage que l’animal a causé, soit que l’animal fût sous sa garde, soit qu’il fût égaré ou échappé.'),
  A('civ', '1244', 'Responsabilité du fait de la ruine d’un bâtiment', 'Le propriétaire d’un bâtiment est responsable du dommage causé par sa ruine, lorsqu’elle est arrivée par une suite du défaut d’entretien ou par le vice de sa construction.'),
  A('civ', '1245', 'Responsabilité du fait des produits défectueux', 'Le producteur est responsable du dommage causé par un défaut de son produit, qu’il soit ou non lié par un contrat avec la victime.'),
  A('civ', '1253', 'Troubles anormaux de voisinage', 'Le propriétaire, le locataire, l’occupant sans titre, le bénéficiaire d’un titre ayant pour objet principal de l’autoriser à occuper ou à exploiter un fonds, le maître d’ouvrage ou celui qui en exerce les pouvoirs qui est à l’origine d’un trouble excédant les inconvénients normaux de voisinage est responsable de plein droit du dommage qui en résulte. Une exonération est prévue lorsque le trouble provient d’activités préexistantes, conformes aux lois et règlements et poursuivies dans les mêmes conditions (loi du 15 avril 2024).', true),
  A('civ', '1302', 'Paiement de l’indu', 'Tout paiement suppose une dette ; ce qui a été reçu sans être dû est sujet à restitution. La restitution n’est pas admise à l’égard des obligations naturelles qui ont été volontairement acquittées.'),
  A('civ', '1303', 'Enrichissement injustifié', 'En dehors des cas de gestion d’affaires et de paiement de l’indu, celui qui bénéficie d’un enrichissement injustifié au détriment d’autrui doit, à celui qui s’en trouve appauvri, une indemnité égale à la moindre des deux valeurs de l’enrichissement et de l’appauvrissement.'),
  A('civ', '1304', 'Obligation conditionnelle', 'L’obligation est conditionnelle lorsqu’elle dépend d’un événement futur et incertain. La condition est suspensive lorsque son accomplissement rend l’obligation pure et simple. Elle est résolutoire lorsque son accomplissement entraîne l’anéantissement de l’obligation.'),
  A('civ', '1310', 'Solidarité', 'La solidarité est légale ou conventionnelle ; elle ne se présume pas.'),
  A('civ', '1341-1', 'Action oblique', 'Lorsque la carence du débiteur dans l’exercice de ses droits et actions à caractère patrimonial compromet les droits de son créancier, celui-ci peut les exercer pour le compte de son débiteur, à l’exception de ceux qui sont exclusivement rattachés à sa personne.'),
  A('civ', '1341-2', 'Action paulienne', 'Le créancier peut aussi agir en son nom personnel pour faire déclarer inopposables à son égard les actes faits par son débiteur en fraude de ses droits, à charge d’établir, s’il s’agit d’un acte à titre onéreux, que le tiers cocontractant avait connaissance de la fraude.'),
  A('civ', '1342', 'Le paiement', 'Le paiement est l’exécution volontaire de la prestation due. Il doit être fait sitôt que la dette devient exigible. Il libère le débiteur à l’égard du créancier et éteint la dette, sauf lorsque la loi ou le contrat prévoit une subrogation dans les droits du créancier.'),
  A('civ', '1347', 'La compensation', 'La compensation est l’extinction simultanée d’obligations réciproques entre deux personnes. Elle s’opère, sous réserve d’être invoquée, à due concurrence, à la date où ses conditions se trouvent réunies.'),
  A('civ', '1353', 'Charge de la preuve', 'Celui qui réclame l’exécution d’une obligation doit la prouver. Réciproquement, celui qui se prétend libéré doit justifier le paiement ou le fait qui a produit l’extinction de son obligation.'),
  A('civ', '1355', 'Autorité de la chose jugée', 'L’autorité de la chose jugée n’a lieu qu’à l’égard de ce qui a fait l’objet du jugement. Il faut que la chose demandée soit la même ; que la demande soit fondée sur la même cause ; que la demande soit entre les mêmes parties, et formée par elles et contre elles en la même qualité.'),
  A('civ', '1359', 'Preuve des actes juridiques', 'L’acte juridique portant sur une somme ou une valeur excédant un montant fixé par décret (1 500 euros) doit être prouvé par écrit sous signature privée ou authentique. Il ne peut être prouvé outre ou contre un écrit établissant un acte juridique, même si la somme ou la valeur n’excède pas ce montant, que par un autre écrit sous signature privée ou authentique.', true),
  A('civ', '1366', 'Écrit électronique', 'L’écrit électronique a la même force probante que l’écrit sur support papier, sous réserve que puisse être dûment identifiée la personne dont il émane et qu’il soit établi et conservé dans des conditions de nature à en garantir l’intégrité.'),
  A('civ', '1582', 'Définition de la vente', 'La vente est une convention par laquelle l’un s’oblige à livrer une chose, et l’autre à la payer. Elle peut être faite par acte authentique ou sous seing privé.'),
  A('civ', '1583', 'Transfert de propriété solo consensu', 'Elle est parfaite entre les parties, et la propriété est acquise de droit à l’acheteur à l’égard du vendeur, dès qu’on est convenu de la chose et du prix, quoique la chose n’ait pas encore été livrée ni le prix payé.'),
  A('civ', '1641', 'Garantie des vices cachés', 'Le vendeur est tenu de la garantie à raison des défauts cachés de la chose vendue qui la rendent impropre à l’usage auquel on la destine, ou qui diminuent tellement cet usage que l’acheteur ne l’aurait pas acquise, ou n’en aurait donné qu’un moindre prix, s’il les avait connus.'),
  A('civ', '1648', 'Délai de l’action en garantie des vices cachés', 'L’action résultant des vices rédhibitoires doit être intentée par l’acquéreur dans un délai de deux ans à compter de la découverte du vice. (L’alinéa 2 prévoit un délai spécial pour les vices de construction apparents.)', true),
  A('civ', '1709', 'Définition du bail', 'Le louage des choses est un contrat par lequel l’une des parties s’oblige à faire jouir l’autre d’une chose pendant un certain temps, et moyennant un certain prix que celle-ci s’oblige de lui payer.'),
  A('civ', '1832', 'Définition de la société', 'La société est instituée par deux ou plusieurs personnes qui conviennent par un contrat d’affecter à une entreprise commune des biens ou leur industrie en vue de partager le bénéfice ou de profiter de l’économie qui pourra en résulter. Elle peut être instituée, dans les cas prévus par la loi, par l’acte de volonté d’une seule personne. Les associés s’engagent à contribuer aux pertes.'),
  A('civ', '1833', 'Objet licite et intérêt social', 'Toute société doit avoir un objet licite et être constituée dans l’intérêt commun des associés. La société est gérée dans son intérêt social, en prenant en considération les enjeux sociaux et environnementaux de son activité.'),
  A('civ', '1984', 'Définition du mandat', 'Le mandat ou procuration est un acte par lequel une personne donne à une autre le pouvoir de faire quelque chose pour le mandant et en son nom. Le contrat ne se forme que par l’acceptation du mandataire.'),
  A('civ', '2224', 'Prescription de droit commun', 'Les actions personnelles ou mobilières se prescrivent par cinq ans à compter du jour où le titulaire d’un droit a connu ou aurait dû connaître les faits lui permettant de l’exercer.'),
  A('civ', '2226', 'Prescription du dommage corporel', 'L’action en responsabilité née à raison d’un événement ayant entraîné un dommage corporel, engagée par la victime directe ou indirecte des préjudices qui en résultent, se prescrit par dix ans à compter de la date de la consolidation du dommage initial ou aggravé. (Délai porté à vingt ans pour les tortures, actes de barbarie et violences ou agressions sexuelles sur mineur.)', true),
  A('civ', '2232', 'Délai butoir', 'Le report du point de départ, la suspension ou l’interruption de la prescription ne peut avoir pour effet de porter le délai de la prescription extinctive au-delà de vingt ans à compter du jour de la naissance du droit. (L’alinéa 2 énumère des exceptions.)', true),
  A('civ', '2258', 'Prescription acquisitive', 'La prescription acquisitive est un moyen d’acquérir un bien ou un droit par l’effet de la possession sans que celui qui l’allègue soit obligé d’en rapporter un titre ou qu’on puisse lui opposer l’exception déduite de la mauvaise foi.'),
  A('civ', '2261', 'Qualités de la possession', 'Pour pouvoir prescrire, il faut une possession continue et non interrompue, paisible, publique, non équivoque, et à titre de propriétaire.'),
  A('civ', '2272', 'Usucapion immobilière', 'Le délai de prescription requis pour acquérir la propriété immobilière est de trente ans. Toutefois, celui qui acquiert de bonne foi et par juste titre un immeuble en prescrit la propriété par dix ans.'),
  A('civ', '2276', 'En fait de meubles, possession vaut titre', 'En fait de meubles, la possession vaut titre. Néanmoins, celui qui a perdu ou auquel il a été volé une chose peut la revendiquer pendant trois ans à compter du jour de la perte ou du vol, contre celui dans les mains duquel il la trouve ; sauf à celui-ci son recours contre celui duquel il la tient.'),
  A('civ', '2284', 'Droit de gage général', 'Quiconque s’est obligé personnellement, est tenu de remplir son engagement sur tous ses biens mobiliers et immobiliers, présents et à venir.'),
  A('civ', '2285', 'Égalité des créanciers chirographaires', 'Les biens du débiteur sont le gage commun de ses créanciers ; et le prix s’en distribue entre eux par contribution, à moins qu’il n’y ait entre les créanciers des causes légitimes de préférence.'),

  // ===================== CONSTITUTION 1958 =====================
  A('const', '1', 'Caractères de la République', 'La France est une République indivisible, laïque, démocratique et sociale. Elle assure l’égalité devant la loi de tous les citoyens sans distinction d’origine, de race ou de religion. Elle respecte toutes les croyances. Son organisation est décentralisée. La loi favorise l’égal accès des femmes et des hommes aux mandats électoraux et fonctions électives, ainsi qu’aux responsabilités professionnelles et sociales.'),
  A('const', '2', 'Langue, emblème, devise et principe', 'La langue de la République est le français. L’emblème national est le drapeau tricolore, bleu, blanc, rouge. L’hymne national est « La Marseillaise ». La devise de la République est « Liberté, Égalité, Fraternité ». Son principe est : gouvernement du peuple, par le peuple et pour le peuple.'),
  A('const', '3', 'Souveraineté nationale', 'La souveraineté nationale appartient au peuple qui l’exerce par ses représentants et par la voie du référendum. Aucune section du peuple ni aucun individu ne peut s’en attribuer l’exercice. Le suffrage peut être direct ou indirect dans les conditions prévues par la Constitution. Il est toujours universel, égal et secret.', true),
  A('const', '5', 'Rôle du Président de la République', 'Le Président de la République veille au respect de la Constitution. Il assure, par son arbitrage, le fonctionnement régulier des pouvoirs publics ainsi que la continuité de l’État. Il est le garant de l’indépendance nationale, de l’intégrité du territoire et du respect des traités.'),
  A('const', '6', 'Élection du Président', 'Le Président de la République est élu pour cinq ans au suffrage universel direct. Nul ne peut exercer plus de deux mandats consécutifs. Les modalités d’application du présent article sont fixées par une loi organique.'),
  A('const', '8', 'Nomination du Premier ministre', 'Le Président de la République nomme le Premier ministre. Il met fin à ses fonctions sur la présentation par celui-ci de la démission du Gouvernement. Sur la proposition du Premier ministre, il nomme les autres membres du Gouvernement et met fin à leurs fonctions.'),
  A('const', '11', 'Référendum législatif', 'Le Président de la République, sur proposition du Gouvernement pendant la durée des sessions ou sur proposition conjointe des deux assemblées, peut soumettre au référendum tout projet de loi portant sur l’organisation des pouvoirs publics, sur des réformes relatives à la politique économique, sociale ou environnementale de la nation et aux services publics qui y concourent, ou tendant à autoriser la ratification d’un traité. Depuis 2008, un référendum d’initiative partagée est possible à l’initiative d’un cinquième des parlementaires soutenue par un dixième des électeurs.', true),
  A('const', '12', 'Dissolution', 'Le Président de la République peut, après consultation du Premier ministre et des présidents des assemblées, prononcer la dissolution de l’Assemblée nationale. Les élections générales ont lieu vingt jours au moins et quarante jours au plus après la dissolution. Il ne peut être procédé à une nouvelle dissolution dans l’année qui suit ces élections.', true),
  A('const', '16', 'Pouvoirs exceptionnels', 'Lorsque les institutions de la République, l’indépendance de la Nation, l’intégrité de son territoire ou l’exécution de ses engagements internationaux sont menacées d’une manière grave et immédiate et que le fonctionnement régulier des pouvoirs publics constitutionnels est interrompu, le Président de la République prend les mesures exigées par ces circonstances, après consultation officielle du Premier ministre, des présidents des assemblées ainsi que du Conseil constitutionnel. Le Parlement se réunit de plein droit ; le Conseil constitutionnel peut être saisi après trente jours.', true),
  A('const', '20', 'Rôle du Gouvernement', 'Le Gouvernement détermine et conduit la politique de la nation. Il dispose de l’administration et de la force armée. Il est responsable devant le Parlement dans les conditions et suivant les procédures prévues aux articles 49 et 50.'),
  A('const', '21', 'Rôle du Premier ministre', 'Le Premier ministre dirige l’action du Gouvernement. Il est responsable de la Défense nationale. Il assure l’exécution des lois. Sous réserve des dispositions de l’article 13, il exerce le pouvoir réglementaire et nomme aux emplois civils et militaires.', true),
  A('const', '24', 'Rôle du Parlement', 'Le Parlement vote la loi. Il contrôle l’action du Gouvernement. Il évalue les politiques publiques. Il comprend l’Assemblée nationale et le Sénat. Les députés sont élus au suffrage direct ; le Sénat, élu au suffrage indirect, assure la représentation des collectivités territoriales.', true),
  A('const', '34', 'Domaine de la loi', 'La loi fixe les règles concernant notamment les droits civiques et les garanties fondamentales accordées aux citoyens pour l’exercice des libertés publiques, la nationalité, l’état et la capacité des personnes, la détermination des crimes et délits et des peines, la procédure pénale, l’assiette, le taux et les modalités de recouvrement des impositions. Elle détermine les principes fondamentaux de l’organisation de la défense, de la libre administration des collectivités territoriales, de l’enseignement, du régime de la propriété et des obligations civiles et commerciales, du droit du travail et de la sécurité sociale.', true),
  A('const', '37', 'Domaine du règlement', 'Les matières autres que celles qui sont du domaine de la loi ont un caractère réglementaire. Les textes de forme législative intervenus en ces matières peuvent être modifiés par décrets pris après avis du Conseil d’État (ou, pour ceux postérieurs à 1958, après déclaration de leur caractère réglementaire par le Conseil constitutionnel).', true),
  A('const', '38', 'Ordonnances', 'Le Gouvernement peut, pour l’exécution de son programme, demander au Parlement l’autorisation de prendre par ordonnances, pendant un délai limité, des mesures qui sont normalement du domaine de la loi. Les ordonnances, prises en Conseil des ministres après avis du Conseil d’État, entrent en vigueur dès leur publication mais deviennent caduques si le projet de loi de ratification n’est pas déposé avant la date fixée par la loi d’habilitation. Elles ne peuvent être ratifiées que de manière expresse.', true),
  A('const', '49', 'Engagement de responsabilité du Gouvernement', 'Le Premier ministre peut engager la responsabilité du Gouvernement sur son programme ou une déclaration de politique générale (al. 1). L’Assemblée nationale peut mettre en cause cette responsabilité par une motion de censure signée par un dixième de ses membres et adoptée à la majorité absolue (al. 2). Le Premier ministre peut, après délibération du Conseil des ministres, engager la responsabilité du Gouvernement sur le vote d’un projet de loi de finances ou de financement de la sécurité sociale, et sur un autre texte par session : le texte est adopté sauf si une motion de censure est votée (al. 3).', true),
  A('const', '55', 'Supériorité des traités sur les lois', 'Les traités ou accords régulièrement ratifiés ou approuvés ont, dès leur publication, une autorité supérieure à celle des lois, sous réserve, pour chaque accord ou traité, de son application par l’autre partie.'),
  A('const', '61', 'Contrôle de constitutionnalité a priori', 'Les lois organiques, avant leur promulgation, les propositions de loi référendaire et les règlements des assemblées parlementaires sont obligatoirement soumis au Conseil constitutionnel. Les lois ordinaires peuvent lui être déférées, avant leur promulgation, par le Président de la République, le Premier ministre, le président de l’Assemblée nationale, le président du Sénat ou soixante députés ou soixante sénateurs. Le Conseil statue dans le délai d’un mois (huit jours en cas d’urgence).', true),
  A('const', '61-1', 'Question prioritaire de constitutionnalité', 'Lorsque, à l’occasion d’une instance en cours devant une juridiction, il est soutenu qu’une disposition législative porte atteinte aux droits et libertés que la Constitution garantit, le Conseil constitutionnel peut être saisi de cette question sur renvoi du Conseil d’État ou de la Cour de cassation qui se prononce dans un délai déterminé. Une loi organique détermine les conditions d’application du présent article.'),
  A('const', '62', 'Effets des décisions du Conseil constitutionnel', 'Une disposition déclarée inconstitutionnelle sur le fondement de l’article 61 ne peut être promulguée ni mise en application. Une disposition déclarée inconstitutionnelle sur le fondement de l’article 61-1 est abrogée à compter de la publication de la décision du Conseil constitutionnel ou d’une date ultérieure fixée par cette décision. Les décisions du Conseil constitutionnel ne sont susceptibles d’aucun recours. Elles s’imposent aux pouvoirs publics et à toutes les autorités administratives et juridictionnelles.', true),
  A('const', '66', 'Autorité judiciaire gardienne de la liberté individuelle', 'Nul ne peut être arbitrairement détenu. L’autorité judiciaire, gardienne de la liberté individuelle, assure le respect de ce principe dans les conditions prévues par la loi.'),
  A('const', '66-1', 'Abolition de la peine de mort', 'Nul ne peut être condamné à la peine de mort.'),
  A('const', '88-1', 'Participation à l’Union européenne', 'La République participe à l’Union européenne constituée d’États qui ont choisi librement d’exercer en commun certaines de leurs compétences en vertu du traité sur l’Union européenne et du traité sur le fonctionnement de l’Union européenne, tels qu’ils résultent du traité signé à Lisbonne le 13 décembre 2007.'),
  A('const', '89', 'Révision de la Constitution', 'L’initiative de la révision appartient concurremment au Président de la République sur proposition du Premier ministre et aux membres du Parlement. Le projet ou la proposition doit être voté par les deux assemblées en termes identiques, puis approuvé par référendum ; un projet de révision peut toutefois être adopté par le Congrès à la majorité des trois cinquièmes des suffrages exprimés. Aucune révision ne peut être engagée lorsqu’il est porté atteinte à l’intégrité du territoire. La forme républicaine du Gouvernement ne peut faire l’objet d’une révision.', true),

  // ===================== DDHC 1789 =====================
  A('ddhc', '1', 'Liberté et égalité', 'Les hommes naissent et demeurent libres et égaux en droits. Les distinctions sociales ne peuvent être fondées que sur l’utilité commune.'),
  A('ddhc', '2', 'Droits naturels', 'Le but de toute association politique est la conservation des droits naturels et imprescriptibles de l’Homme. Ces droits sont la liberté, la propriété, la sûreté, et la résistance à l’oppression.'),
  A('ddhc', '4', 'Définition de la liberté', 'La liberté consiste à pouvoir faire tout ce qui ne nuit pas à autrui : ainsi, l’exercice des droits naturels de chaque homme n’a de bornes que celles qui assurent aux autres Membres de la Société la jouissance de ces mêmes droits. Ces bornes ne peuvent être déterminées que par la Loi.'),
  A('ddhc', '5', 'Ce que la loi peut défendre', 'La Loi n’a le droit de défendre que les actions nuisibles à la Société. Tout ce qui n’est pas défendu par la Loi ne peut être empêché, et nul ne peut être contraint à faire ce qu’elle n’ordonne pas.'),
  A('ddhc', '6', 'La loi, expression de la volonté générale', 'La Loi est l’expression de la volonté générale. Tous les Citoyens ont droit de concourir personnellement, ou par leurs Représentants, à sa formation. Elle doit être la même pour tous, soit qu’elle protège, soit qu’elle punisse. Tous les Citoyens étant égaux à ses yeux sont également admissibles à toutes dignités, places et emplois publics, selon leur capacité, et sans autre distinction que celle de leurs vertus et de leurs talents.'),
  A('ddhc', '7', 'Sûreté et légalité des arrestations', 'Nul homme ne peut être accusé, arrêté ni détenu que dans les cas déterminés par la Loi, et selon les formes qu’elle a prescrites. Ceux qui sollicitent, expédient, exécutent ou font exécuter des ordres arbitraires, doivent être punis ; mais tout citoyen appelé ou saisi en vertu de la Loi doit obéir à l’instant : il se rend coupable par la résistance.'),
  A('ddhc', '8', 'Légalité et nécessité des peines', 'La Loi ne doit établir que des peines strictement et évidemment nécessaires, et nul ne peut être puni qu’en vertu d’une Loi établie et promulguée antérieurement au délit, et légalement appliquée.'),
  A('ddhc', '9', 'Présomption d’innocence', 'Tout homme étant présumé innocent jusqu’à ce qu’il ait été déclaré coupable, s’il est jugé indispensable de l’arrêter, toute rigueur qui ne serait pas nécessaire pour s’assurer de sa personne doit être sévèrement réprimée par la loi.'),
  A('ddhc', '10', 'Liberté d’opinion', 'Nul ne doit être inquiété pour ses opinions, même religieuses, pourvu que leur manifestation ne trouble pas l’ordre public établi par la Loi.'),
  A('ddhc', '11', 'Liberté d’expression', 'La libre communication des pensées et des opinions est un des droits les plus précieux de l’Homme : tout Citoyen peut donc parler, écrire, imprimer librement, sauf à répondre de l’abus de cette liberté dans les cas déterminés par la Loi.'),
  A('ddhc', '13', 'Contribution commune', 'Pour l’entretien de la force publique, et pour les dépenses d’administration, une contribution commune est indispensable : elle doit être également répartie entre tous les citoyens, en raison de leurs facultés.'),
  A('ddhc', '16', 'Garantie des droits et séparation des pouvoirs', 'Toute Société dans laquelle la garantie des Droits n’est pas assurée, ni la séparation des Pouvoirs déterminée, n’a point de Constitution.'),
  A('ddhc', '17', 'Droit de propriété', 'La propriété étant un droit inviolable et sacré, nul ne peut en être privé, si ce n’est lorsque la nécessité publique, légalement constatée, l’exige évidemment, et sous la condition d’une juste et préalable indemnité.'),

  // ===================== CODE PÉNAL =====================
  A('pen', '111-1', 'Classification tripartite des infractions', 'Les infractions pénales sont classées, suivant leur gravité, en crimes, délits et contraventions.'),
  A('pen', '111-2', 'Compétences de la loi et du règlement', 'La loi détermine les crimes et délits et fixe les peines applicables à leurs auteurs. Le règlement détermine les contraventions et fixe, dans les limites et selon les distinctions établies par la loi, les peines applicables aux contrevenants.'),
  A('pen', '111-3', 'Principe de légalité criminelle', 'Nul ne peut être puni pour un crime ou pour un délit dont les éléments ne sont pas définis par la loi, ou pour une contravention dont les éléments ne sont pas définis par le règlement. Nul ne peut être puni d’une peine qui n’est pas prévue par la loi, si l’infraction est un crime ou un délit, ou par le règlement, si l’infraction est une contravention.'),
  A('pen', '111-4', 'Interprétation stricte', 'La loi pénale est d’interprétation stricte.'),
  A('pen', '112-1', 'Application de la loi pénale dans le temps', 'Sont seuls punissables les faits constitutifs d’une infraction à la date à laquelle ils ont été commis. Peuvent seules être prononcées les peines légalement applicables à la même date. Toutefois, les dispositions nouvelles s’appliquent aux infractions commises avant leur entrée en vigueur et n’ayant pas donné lieu à une condamnation passée en force de chose jugée lorsqu’elles sont moins sévères que les dispositions anciennes.'),
  A('pen', '113-2', 'Compétence territoriale', 'La loi pénale française est applicable aux infractions commises sur le territoire de la République. L’infraction est réputée commise sur le territoire de la République dès lors qu’un de ses faits constitutifs a eu lieu sur ce territoire.'),
  A('pen', '121-1', 'Responsabilité personnelle', 'Nul n’est responsable pénalement que de son propre fait.'),
  A('pen', '121-2', 'Responsabilité des personnes morales', 'Les personnes morales, à l’exclusion de l’État, sont responsables pénalement, selon les distinctions des articles 121-4 à 121-7, des infractions commises, pour leur compte, par leurs organes ou représentants. Les collectivités territoriales ne le sont que pour les activités susceptibles de délégation de service public. Leur responsabilité n’exclut pas celle des personnes physiques auteurs ou complices des mêmes faits.', true),
  A('pen', '121-3', 'Élément moral', 'Il n’y a point de crime ou de délit sans intention de le commettre. Toutefois, lorsque la loi le prévoit, il y a délit en cas de mise en danger délibérée de la personne d’autrui, et en cas de faute d’imprudence, de négligence ou de manquement à une obligation de prudence ou de sécurité. Les personnes physiques qui n’ont pas causé directement le dommage mais qui ont créé ou contribué à créer la situation, ou n’ont pas pris les mesures permettant de l’éviter, ne sont responsables que s’il est établi qu’elles ont violé de façon manifestement délibérée une obligation particulière de prudence ou de sécurité, ou commis une faute caractérisée exposant autrui à un risque d’une particulière gravité qu’elles ne pouvaient ignorer (loi Fauchon du 10 juillet 2000). Il n’y a point de contravention en cas de force majeure.', true),
  A('pen', '121-4', 'Auteur de l’infraction', 'Est auteur de l’infraction la personne qui : 1° Commet les faits incriminés ; 2° Tente de commettre un crime ou, dans les cas prévus par la loi, un délit.'),
  A('pen', '121-5', 'Tentative', 'La tentative est constituée dès lors que, manifestée par un commencement d’exécution, elle n’a été suspendue ou n’a manqué son effet qu’en raison de circonstances indépendantes de la volonté de son auteur.'),
  A('pen', '121-6', 'Pénalité du complice', 'Sera puni comme auteur le complice de l’infraction, au sens de l’article 121-7.'),
  A('pen', '121-7', 'Complicité', 'Est complice d’un crime ou d’un délit la personne qui sciemment, par aide ou assistance, en a facilité la préparation ou la consommation. Est également complice la personne qui par don, promesse, menace, ordre, abus d’autorité ou de pouvoir aura provoqué à une infraction ou donné des instructions pour la commettre.'),
  A('pen', '122-1', 'Trouble psychique ou neuropsychique', 'N’est pas pénalement responsable la personne qui était atteinte, au moment des faits, d’un trouble psychique ou neuropsychique ayant aboli son discernement ou le contrôle de ses actes. La personne dont le discernement a seulement été altéré demeure punissable ; la juridiction en tient compte pour fixer la peine (réduction du maximum encouru). Depuis la loi du 24 janvier 2022, l’irresponsabilité est en principe exclue lorsque l’abolition résulte de la consommation volontaire de substances psychoactives dans le dessein de commettre l’infraction (art. 122-1-1).', true),
  A('pen', '122-2', 'Contrainte', 'N’est pas pénalement responsable la personne qui a agi sous l’empire d’une force ou d’une contrainte à laquelle elle n’a pu résister.'),
  A('pen', '122-3', 'Erreur sur le droit', 'N’est pas pénalement responsable la personne qui justifie avoir cru, par une erreur sur le droit qu’elle n’était pas en mesure d’éviter, pouvoir légitimement accomplir l’acte.'),
  A('pen', '122-4', 'Ordre de la loi et commandement de l’autorité légitime', 'N’est pas pénalement responsable la personne qui accomplit un acte prescrit ou autorisé par des dispositions législatives ou réglementaires. N’est pas pénalement responsable la personne qui accomplit un acte commandé par l’autorité légitime, sauf si cet acte est manifestement illégal.'),
  A('pen', '122-5', 'Légitime défense', 'N’est pas pénalement responsable la personne qui, devant une atteinte injustifiée envers elle-même ou autrui, accomplit, dans le même temps, un acte commandé par la nécessité de la légitime défense d’elle-même ou d’autrui, sauf s’il y a disproportion entre les moyens de défense employés et la gravité de l’atteinte. N’est pas pénalement responsable la personne qui, pour interrompre l’exécution d’un crime ou d’un délit contre un bien, accomplit un acte de défense, autre qu’un homicide volontaire, lorsque cet acte est strictement nécessaire au but poursuivi dès lors que les moyens employés sont proportionnés à la gravité de l’infraction.'),
  A('pen', '122-6', 'Présomptions de légitime défense', 'Est présumé avoir agi en état de légitime défense celui qui accomplit l’acte : 1° Pour repousser, de nuit, l’entrée par effraction, violence ou ruse dans un lieu habité ; 2° Pour se défendre contre les auteurs de vols ou de pillages exécutés avec violence.'),
  A('pen', '122-7', 'État de nécessité', 'N’est pas pénalement responsable la personne qui, face à un danger actuel ou imminent qui menace elle-même, autrui ou un bien, accomplit un acte nécessaire à la sauvegarde de la personne ou du bien, sauf s’il y a disproportion entre les moyens employés et la gravité de la menace.'),
  A('pen', '130-1', 'Fonctions de la peine', 'Afin d’assurer la protection de la société, de prévenir la commission de nouvelles infractions et de restaurer l’équilibre social, dans le respect des intérêts de la victime, la peine a pour fonctions : 1° De sanctionner l’auteur de l’infraction ; 2° De favoriser son amendement, son insertion ou sa réinsertion.'),
  A('pen', '221-1', 'Meurtre', 'Le fait de donner volontairement la mort à autrui constitue un meurtre. Il est puni de trente ans de réclusion criminelle.'),
  A('pen', '221-3', 'Assassinat', 'Le meurtre commis avec préméditation ou avec guet-apens constitue un assassinat. Il est puni de la réclusion criminelle à perpétuité. (Les alinéas suivants concernent la période de sûreté.)', true),
  A('pen', '221-6', 'Homicide involontaire', 'Le fait de causer, dans les conditions et selon les distinctions prévues à l’article 121-3, par maladresse, imprudence, inattention, négligence ou manquement à une obligation de prudence ou de sécurité imposée par la loi ou le règlement, la mort d’autrui constitue un homicide involontaire puni de trois ans d’emprisonnement et de 45 000 euros d’amende. (Peines aggravées en cas de violation manifestement délibérée d’une obligation particulière de prudence.)', true),
  A('pen', '222-1', 'Tortures et actes de barbarie', 'Le fait de soumettre une personne à des tortures ou à des actes de barbarie est puni de quinze ans de réclusion criminelle. (Les alinéas suivants concernent la période de sûreté.)', true),
  A('pen', '222-33-2', 'Harcèlement moral au travail', 'Le fait de harceler autrui par des propos ou comportements répétés ayant pour objet ou pour effet une dégradation des conditions de travail susceptible de porter atteinte à ses droits et à sa dignité, d’altérer sa santé physique ou mentale ou de compromettre son avenir professionnel, est puni de deux ans d’emprisonnement et de 30 000 € d’amende.'),
  A('pen', '223-1', 'Mise en danger de la personne d’autrui', 'Le fait d’exposer directement autrui à un risque immédiat de mort ou de blessures de nature à entraîner une mutilation ou une infirmité permanente par la violation manifestement délibérée d’une obligation particulière de prudence ou de sécurité imposée par la loi ou le règlement est puni d’un an d’emprisonnement et de 15 000 euros d’amende.'),
  A('pen', '223-6', 'Omission de porter secours', 'Quiconque pouvant empêcher par son action immédiate, sans risque pour lui ou pour les tiers, soit un crime, soit un délit contre l’intégrité corporelle de la personne s’abstient volontairement de le faire est puni de cinq ans d’emprisonnement et de 75 000 euros d’amende. Sera puni des mêmes peines quiconque s’abstient volontairement de porter à une personne en péril l’assistance que, sans risque pour lui ou pour les tiers, il pouvait lui prêter soit par son action personnelle, soit en provoquant un secours.', true),
  A('pen', '311-1', 'Vol', 'Le vol est la soustraction frauduleuse de la chose d’autrui.'),
  A('pen', '311-3', 'Peine du vol simple', 'Le vol est puni de trois ans d’emprisonnement et de 45 000 euros d’amende.'),
  A('pen', '312-1', 'Extorsion', 'L’extorsion est le fait d’obtenir par violence, menace de violences ou contrainte soit une signature, un engagement ou une renonciation, soit la révélation d’un secret, soit la remise de fonds, de valeurs ou d’un bien quelconque. L’extorsion est punie de sept ans d’emprisonnement et de 100 000 euros d’amende.'),
  A('pen', '313-1', 'Escroquerie', 'L’escroquerie est le fait, soit par l’usage d’un faux nom ou d’une fausse qualité, soit par l’abus d’une qualité vraie, soit par l’emploi de manœuvres frauduleuses, de tromper une personne physique ou morale et de la déterminer ainsi, à son préjudice ou au préjudice d’un tiers, à remettre des fonds, des valeurs ou un bien quelconque, à fournir un service ou à consentir un acte opérant obligation ou décharge. L’escroquerie est punie de cinq ans d’emprisonnement et de 375 000 euros d’amende.'),
  A('pen', '314-1', 'Abus de confiance', 'L’abus de confiance est le fait par une personne de détourner, au préjudice d’autrui, des fonds, des valeurs ou un bien quelconque qui lui ont été remis et qu’elle a acceptés à charge de les rendre, de les représenter ou d’en faire un usage déterminé. L’abus de confiance est puni de cinq ans d’emprisonnement et de 375 000 euros d’amende.'),
  A('pen', '321-1', 'Recel', 'Le recel est le fait de dissimuler, de détenir ou de transmettre une chose, ou de faire office d’intermédiaire afin de la transmettre, en sachant que cette chose provient d’un crime ou d’un délit. Constitue également un recel le fait, en connaissance de cause, de bénéficier, par tout moyen, du produit d’un crime ou d’un délit. Le recel est puni de cinq ans d’emprisonnement et de 375 000 euros d’amende.'),
  A('pen', '441-1', 'Faux et usage de faux', 'Constitue un faux toute altération frauduleuse de la vérité, de nature à causer un préjudice et accomplie par quelque moyen que ce soit, dans un écrit ou tout autre support d’expression de la pensée qui a pour objet ou qui peut avoir pour effet d’établir la preuve d’un droit ou d’un fait ayant des conséquences juridiques. Le faux et l’usage de faux sont punis de trois ans d’emprisonnement et de 45 000 euros d’amende.'),
  A('pen', '432-11', 'Corruption passive et trafic d’influence (agent public)', 'Est puni de dix ans d’emprisonnement et d’une amende de 1 000 000 € (dont le montant peut être porté au double du produit de l’infraction) le fait, par une personne dépositaire de l’autorité publique, chargée d’une mission de service public ou investie d’un mandat électif public, de solliciter ou d’agréer, sans droit, à tout moment, directement ou indirectement, des offres, des promesses, des dons, des présents ou des avantages quelconques, pour elle-même ou pour autrui, pour accomplir ou s’abstenir d’accomplir un acte de sa fonction, ou pour abuser de son influence en vue de faire obtenir une décision favorable.', true),

  // ===================== CODE DE PROCÉDURE PÉNALE =====================
  A('cpp', 'préliminaire', 'Principes directeurs du procès pénal', 'La procédure pénale doit être équitable et contradictoire et préserver l’équilibre des droits des parties. Elle doit garantir la séparation des autorités chargées de l’action publique et des autorités de jugement. Les personnes se trouvant dans des conditions semblables et poursuivies pour les mêmes infractions doivent être jugées selon les mêmes règles. Toute personne suspectée ou poursuivie est présumée innocente tant que sa culpabilité n’a pas été établie. Il doit être définitivement statué sur l’accusation dans un délai raisonnable.', true),
  A('cpp', '1', 'Action publique', 'L’action publique pour l’application des peines est mise en mouvement et exercée par les magistrats ou par les fonctionnaires auxquels elle est confiée par la loi. Cette action peut aussi être mise en mouvement par la partie lésée, dans les conditions déterminées par le présent code.'),
  A('cpp', '2', 'Action civile', 'L’action civile en réparation du dommage causé par un crime, un délit ou une contravention appartient à tous ceux qui ont personnellement souffert du dommage directement causé par l’infraction. La renonciation à l’action civile ne peut arrêter ni suspendre l’exercice de l’action publique, sous réserve des cas visés à l’alinéa 3 de l’article 6.'),
  A('cpp', '6', 'Extinction de l’action publique', 'L’action publique pour l’application de la peine s’éteint par la mort du prévenu, la prescription, l’amnistie, l’abrogation de la loi pénale et la chose jugée. Elle peut aussi s’éteindre par transaction lorsque la loi en dispose expressément, par l’exécution d’une composition pénale ou en cas de retrait de plainte lorsque celle-ci est une condition nécessaire de la poursuite.', true),
  A('cpp', '7', 'Prescription des crimes', 'L’action publique des crimes se prescrit par vingt années révolues à compter du jour où l’infraction a été commise. Elle se prescrit par trente ans pour certains crimes (notamment terrorisme, trafic de stupéfiants, crimes sur mineurs, dont le délai court à compter de la majorité). Les crimes contre l’humanité sont imprescriptibles.', true),
  A('cpp', '8', 'Prescription des délits', 'L’action publique des délits se prescrit par six années révolues à compter du jour où l’infraction a été commise. Des délais spéciaux existent, notamment pour certains délits commis sur des mineurs.', true),
  A('cpp', '9', 'Prescription des contraventions', 'L’action publique des contraventions se prescrit par une année révolue à compter du jour où l’infraction a été commise.'),
  A('cpp', '40-1', 'Opportunité des poursuites', 'Lorsqu’il estime que les faits portés à sa connaissance constituent une infraction commise par une personne dont l’identité et le domicile sont connus et pour laquelle aucune disposition légale ne fait obstacle à la mise en mouvement de l’action publique, le procureur de la République territorialement compétent décide s’il est opportun : 1° Soit d’engager des poursuites ; 2° Soit de mettre en œuvre une procédure alternative aux poursuites ; 3° Soit de classer sans suite la procédure dès lors que les circonstances particulières liées à la commission des faits le justifient.'),
  A('cpp', '53', 'Flagrance', 'Est qualifié crime ou délit flagrant le crime ou le délit qui se commet actuellement, ou qui vient de se commettre. Il y a aussi crime ou délit flagrant lorsque, dans un temps très voisin de l’action, la personne soupçonnée est poursuivie par la clameur publique, ou est trouvée en possession d’objets, ou présente des traces ou indices, laissant penser qu’elle a participé au crime ou au délit. L’enquête de flagrance dure en principe huit jours, prolongeable de huit jours.', true),
  A('cpp', '62-2', 'Définition de la garde à vue', 'La garde à vue est une mesure de contrainte décidée par un officier de police judiciaire, sous le contrôle de l’autorité judiciaire, par laquelle une personne à l’encontre de laquelle il existe une ou plusieurs raisons plausibles de soupçonner qu’elle a commis ou tenté de commettre un crime ou un délit puni d’une peine d’emprisonnement est maintenue à la disposition des enquêteurs. Elle doit constituer l’unique moyen de parvenir à l’un des objectifs fixés par la loi (permettre les investigations, garantir la présentation au magistrat, empêcher les pressions ou la concertation, faire cesser l’infraction…).', true),
  A('cpp', '63-1', 'Droits du gardé à vue', 'La personne placée en garde à vue est immédiatement informée, dans une langue qu’elle comprend, de son placement, de la durée de la mesure, de la qualification et de la date présumées de l’infraction, et de ses droits : faire prévenir un proche et son employeur, être examinée par un médecin, être assistée par un avocat, être assistée par un interprète, consulter certaines pièces, présenter des observations au magistrat, et le droit, lors des auditions, de faire des déclarations, de répondre aux questions ou de se taire.', true),
  A('cpp', '63', 'Durée de la garde à vue', 'La durée de la garde à vue ne peut excéder vingt-quatre heures. Elle peut être prolongée pour un nouveau délai de vingt-quatre heures au plus, sur autorisation écrite et motivée du procureur de la République, si l’infraction est un crime ou un délit puni d’une peine d’emprisonnement supérieure ou égale à un an. Des régimes dérogatoires (criminalité organisée, terrorisme) permettent d’aller jusqu’à 96 heures, voire 144 heures.', true),
  A('cpp', '73', 'Appréhension par tout citoyen', 'Dans les cas de crime flagrant ou de délit flagrant puni d’une peine d’emprisonnement, toute personne a qualité pour en appréhender l’auteur et le conduire devant l’officier de police judiciaire le plus proche.'),
  A('cpp', '137', 'Liberté du mis en examen', 'Toute personne mise en examen, présumée innocente, demeure libre. Toutefois, en raison des nécessités de l’instruction ou à titre de mesure de sûreté, elle peut être astreinte à une ou plusieurs obligations du contrôle judiciaire ou, si celles-ci se révèlent insuffisantes, être assignée à résidence avec surveillance électronique. A titre exceptionnel, si les obligations du contrôle judiciaire ou de l’assignation à résidence ne permettent pas d’atteindre ces objectifs, elle peut être placée en détention provisoire.', true),
  A('cpp', '144', 'Conditions de la détention provisoire', 'La détention provisoire ne peut être ordonnée ou prolongée que s’il est démontré, au regard des éléments précis et circonstanciés résultant de la procédure, qu’elle constitue l’unique moyen de parvenir à l’un des objectifs fixés par la loi (conserver les preuves, empêcher les pressions sur les témoins ou victimes, empêcher une concertation frauduleuse, protéger la personne, garantir son maintien à disposition de la justice, mettre fin à l’infraction ou prévenir son renouvellement, mettre fin au trouble exceptionnel à l’ordre public en matière criminelle) et que ces objectifs ne sauraient être atteints en cas de placement sous contrôle judiciaire ou d’assignation à résidence avec surveillance électronique.', true),
  A('cpp', '368', 'Non bis in idem (cour d’assises)', 'Aucune personne acquittée légalement ne peut plus être reprise ou accusée à raison des mêmes faits, même sous une qualification différente.'),
  A('cpp', '427', 'Liberté de la preuve et intime conviction', 'Hors les cas où la loi en dispose autrement, les infractions peuvent être établies par tout mode de preuve et le juge décide d’après son intime conviction. Le juge ne peut fonder sa décision que sur des preuves qui lui sont apportées au cours des débats et contradictoirement discutées devant lui.'),

  // ===================== CODE DE PROCÉDURE CIVILE =====================
  A('cpc', '1', 'Principe dispositif : maîtrise de l’instance', 'Seules les parties introduisent l’instance, hors les cas où la loi en dispose autrement. Elles ont la liberté d’y mettre fin avant qu’elle ne s’éteigne par l’effet du jugement ou en vertu de la loi.'),
  A('cpc', '4', 'Objet du litige', 'L’objet du litige est déterminé par les prétentions respectives des parties. Ces prétentions sont fixées par l’acte introductif d’instance et par les conclusions en défense. Toutefois l’objet du litige peut être modifié par des demandes incidentes lorsque celles-ci se rattachent aux prétentions originaires par un lien suffisant.'),
  A('cpc', '5', 'Interdiction de statuer ultra et infra petita', 'Le juge doit se prononcer sur tout ce qui est demandé et seulement sur ce qui est demandé.'),
  A('cpc', '6', 'Charge de l’allégation', 'A l’appui de leurs prétentions, les parties ont la charge d’alléguer les faits propres à les fonder.'),
  A('cpc', '9', 'Charge de la preuve', 'Il incombe à chaque partie de prouver conformément à la loi les faits nécessaires au succès de sa prétention.'),
  A('cpc', '12', 'Office du juge', 'Le juge tranche le litige conformément aux règles de droit qui lui sont applicables. Il doit donner ou restituer leur exacte qualification aux faits et actes litigieux sans s’arrêter à la dénomination que les parties en auraient proposée. Toutefois, il ne peut changer la dénomination ou le fondement juridique lorsque les parties, en vertu d’un accord exprès et pour les droits dont elles ont la libre disposition, l’ont lié par les qualifications et points de droit auxquels elles entendent limiter le débat.', true),
  A('cpc', '14', 'Droit d’être entendu', 'Nulle partie ne peut être jugée sans avoir été entendue ou appelée.'),
  A('cpc', '16', 'Principe de la contradiction', 'Le juge doit, en toutes circonstances, faire observer et observer lui-même le principe de la contradiction. Il ne peut retenir, dans sa décision, les moyens, les explications et les documents invoqués ou produits par les parties que si celles-ci ont été à même d’en débattre contradictoirement. Il ne peut fonder sa décision sur les moyens de droit qu’il a relevés d’office sans avoir au préalable invité les parties à présenter leurs observations.'),
  A('cpc', '30', 'Définition de l’action', 'L’action est le droit, pour l’auteur d’une prétention, d’être entendu sur le fond de celle-ci afin que le juge la dise bien ou mal fondée. Pour l’adversaire, l’action est le droit de discuter le bien-fondé de cette prétention.'),
  A('cpc', '31', 'Intérêt et qualité à agir', 'L’action est ouverte à tous ceux qui ont un intérêt légitime au succès ou au rejet d’une prétention, sous réserve des cas dans lesquels la loi attribue le droit d’agir aux seules personnes qu’elle qualifie pour élever ou combattre une prétention, ou pour défendre un intérêt déterminé.'),
  A('cpc', '32', 'Défaut de droit d’agir', 'Est irrecevable toute prétention émise par ou contre une personne dépourvue du droit d’agir.'),
  A('cpc', '71', 'Défense au fond', 'Constitue une défense au fond tout moyen qui tend à faire rejeter comme non justifiée, après examen au fond du droit, la prétention de l’adversaire.'),
  A('cpc', '73', 'Exception de procédure', 'Constitue une exception de procédure tout moyen qui tend soit à faire déclarer la procédure irrégulière ou éteinte, soit à en suspendre le cours.'),
  A('cpc', '74', 'Moment de l’exception de procédure', 'Les exceptions doivent, à peine d’irrecevabilité, être soulevées simultanément et avant toute défense au fond ou fin de non-recevoir. Il en est ainsi alors même que les règles invoquées au soutien de l’exception seraient d’ordre public.', true),
  A('cpc', '122', 'Fin de non-recevoir', 'Constitue une fin de non-recevoir tout moyen qui tend à faire déclarer l’adversaire irrecevable en sa demande, sans examen au fond, pour défaut de droit d’agir, tel le défaut de qualité, le défaut d’intérêt, la prescription, le délai préfix, la chose jugée.'),
  A('cpc', '145', 'Mesures d’instruction in futurum', 'S’il existe un motif légitime de conserver ou d’établir avant tout procès la preuve de faits dont pourrait dépendre la solution d’un litige, les mesures d’instruction légalement admissibles peuvent être ordonnées à la demande de tout intéressé, sur requête ou en référé.'),
  A('cpc', '484', 'Ordonnance de référé', 'L’ordonnance de référé est une décision provisoire rendue à la demande d’une partie, l’autre présente ou appelée, dans les cas où la loi confère à un juge qui n’est pas saisi du principal le pouvoir d’ordonner immédiatement les mesures nécessaires.'),
  A('cpc', '538', 'Délai des voies de recours ordinaires', 'Le délai de recours par une voie ordinaire est d’un mois en matière contentieuse ; il est de quinze jours en matière gracieuse.'),
  A('cpc', '542', 'Objet de l’appel', 'L’appel tend, par la critique du jugement rendu par une juridiction du premier degré, à sa réformation ou à son annulation par la cour d’appel.'),
  A('cpc', '604', 'Objet du pourvoi en cassation', 'Le pourvoi en cassation tend à faire censurer par la Cour de cassation la non-conformité du jugement qu’il attaque aux règles de droit.'),
  A('cpc', '612', 'Délai du pourvoi en cassation', 'Le délai de pourvoi en cassation est de deux mois, sauf disposition contraire.'),
  A('cpc', '641', 'Computation des délais', 'Lorsqu’un délai est exprimé en jours, celui de l’acte, de l’événement, de la décision ou de la notification qui le fait courir ne compte pas. Lorsqu’un délai est exprimé en mois ou en années, ce délai expire le jour du dernier mois ou de la dernière année qui porte le même quantième que le jour de l’acte, de l’événement, de la décision ou de la notification qui fait courir le délai. A défaut d’un quantième identique, le délai expire le dernier jour du mois. Lorsqu’un délai est exprimé en mois et en jours, les mois sont d’abord décomptés, puis les jours.'),
  A('cpc', '642', 'Expiration des délais', 'Tout délai expire le dernier jour à vingt-quatre heures. Le délai qui expirerait normalement un samedi, un dimanche ou un jour férié ou chômé, est prorogé jusqu’au premier jour ouvrable suivant.'),
  A('cpc', '700', 'Frais irrépétibles', 'Le juge condamne la partie tenue aux dépens ou qui perd son procès à payer à l’autre partie la somme qu’il détermine, au titre des frais exposés et non compris dans les dépens (notamment les honoraires d’avocat). Il tient compte de l’équité ou de la situation économique de la partie condamnée.', true),

  // ===================== CEDH =====================
  A('cedh', '2', 'Droit à la vie', 'Le droit de toute personne à la vie est protégé par la loi. La mort ne peut être infligée intentionnellement, sauf dans des cas strictement définis (recours à la force rendu absolument nécessaire pour assurer la défense de toute personne contre la violence illégale, pour effectuer une arrestation régulière ou empêcher une évasion, pour réprimer une émeute ou une insurrection).', true),
  A('cedh', '3', 'Interdiction de la torture', 'Nul ne peut être soumis à la torture ni à des peines ou traitements inhumains ou dégradants.'),
  A('cedh', '5', 'Droit à la liberté et à la sûreté', 'Toute personne a droit à la liberté et à la sûreté. Nul ne peut être privé de sa liberté, sauf dans les cas limitativement énumérés et selon les voies légales. Toute personne arrêtée doit être informée des raisons de son arrestation, être aussitôt traduite devant un juge, et a le droit d’introduire un recours devant un tribunal qui statue à bref délai sur la légalité de sa détention.', true),
  A('cedh', '6', 'Droit à un procès équitable', 'Toute personne a droit à ce que sa cause soit entendue équitablement, publiquement et dans un délai raisonnable, par un tribunal indépendant et impartial, établi par la loi, qui décidera, soit des contestations sur ses droits et obligations de caractère civil, soit du bien-fondé de toute accusation en matière pénale dirigée contre elle. Toute personne accusée d’une infraction est présumée innocente jusqu’à ce que sa culpabilité ait été légalement établie, et dispose notamment du droit d’être informée de l’accusation, de disposer du temps nécessaire à sa défense et de l’assistance d’un défenseur.', true),
  A('cedh', '7', 'Pas de peine sans loi', 'Nul ne peut être condamné pour une action ou une omission qui, au moment où elle a été commise, ne constituait pas une infraction d’après le droit national ou international. De même il n’est infligé aucune peine plus forte que celle qui était applicable au moment où l’infraction a été commise.', true),
  A('cedh', '8', 'Droit au respect de la vie privée et familiale', 'Toute personne a droit au respect de sa vie privée et familiale, de son domicile et de sa correspondance. Il ne peut y avoir ingérence d’une autorité publique dans l’exercice de ce droit que pour autant que cette ingérence est prévue par la loi et qu’elle constitue une mesure qui, dans une société démocratique, est nécessaire à la sécurité nationale, à la sûreté publique, au bien-être économique du pays, à la défense de l’ordre et à la prévention des infractions pénales, à la protection de la santé ou de la morale, ou à la protection des droits et libertés d’autrui.'),
  A('cedh', '9', 'Liberté de pensée, de conscience et de religion', 'Toute personne a droit à la liberté de pensée, de conscience et de religion, ce qui implique la liberté de changer de religion ou de conviction et la liberté de la manifester, individuellement ou collectivement. Cette liberté de manifestation ne peut faire l’objet que des restrictions prévues par la loi et nécessaires dans une société démocratique.', true),
  A('cedh', '10', 'Liberté d’expression', 'Toute personne a droit à la liberté d’expression. Ce droit comprend la liberté d’opinion et la liberté de recevoir ou de communiquer des informations ou des idées sans qu’il puisse y avoir ingérence d’autorités publiques et sans considération de frontière. L’exercice de ces libertés peut être soumis à des formalités, conditions, restrictions ou sanctions prévues par la loi et nécessaires dans une société démocratique (sécurité nationale, protection de la réputation ou des droits d’autrui, autorité et impartialité du pouvoir judiciaire…).', true),
  A('cedh', '11', 'Liberté de réunion et d’association', 'Toute personne a droit à la liberté de réunion pacifique et à la liberté d’association, y compris le droit de fonder avec d’autres des syndicats et de s’affilier à des syndicats pour la défense de ses intérêts. Les restrictions doivent être prévues par la loi et nécessaires dans une société démocratique.', true),
  A('cedh', '13', 'Droit à un recours effectif', 'Toute personne dont les droits et libertés reconnus dans la présente Convention ont été violés, a droit à l’octroi d’un recours effectif devant une instance nationale, alors même que la violation aurait été commise par des personnes agissant dans l’exercice de leurs fonctions officielles.'),
  A('cedh', '14', 'Interdiction de discrimination', 'La jouissance des droits et libertés reconnus dans la Convention doit être assurée, sans distinction aucune, fondée notamment sur le sexe, la race, la couleur, la langue, la religion, les opinions politiques ou toutes autres opinions, l’origine nationale ou sociale, l’appartenance à une minorité nationale, la fortune, la naissance ou toute autre situation.'),
  A('cedh', '35', 'Conditions de recevabilité', 'La Cour ne peut être saisie qu’après l’épuisement des voies de recours internes, tel qu’il est entendu selon les principes de droit international généralement reconnus, et dans un délai de quatre mois à partir de la date de la décision interne définitive.', true),

  // ===================== CODE DU TRAVAIL =====================
  A('trav', 'L. 1121-1', 'Restrictions aux libertés des salariés', 'Nul ne peut apporter aux droits des personnes et aux libertés individuelles et collectives de restrictions qui ne seraient pas justifiées par la nature de la tâche à accomplir ni proportionnées au but recherché.'),
  A('trav', 'L. 1132-1', 'Principe de non-discrimination', 'Aucune personne ne peut être écartée d’une procédure de recrutement ou de nomination ou de l’accès à un stage ou à une période de formation, aucun salarié ne peut être sanctionné, licencié ou faire l’objet d’une mesure discriminatoire, directe ou indirecte, en raison notamment de son origine, de son sexe, de ses mœurs, de son orientation sexuelle, de son identité de genre, de son âge, de sa situation de famille ou de sa grossesse, de ses caractéristiques génétiques, de son appartenance ou non-appartenance à une ethnie, une nation ou une prétendue race, de ses opinions politiques, de ses activités syndicales, de ses convictions religieuses, de son apparence physique, de son nom de famille, de son lieu de résidence ou de son état de santé ou de son handicap.', true),
  A('trav', 'L. 1152-1', 'Harcèlement moral', 'Aucun salarié ne doit subir les agissements répétés de harcèlement moral qui ont pour objet ou pour effet une dégradation de ses conditions de travail susceptible de porter atteinte à ses droits et à sa dignité, d’altérer sa santé physique ou mentale ou de compromettre son avenir professionnel.'),
  A('trav', 'L. 1221-1', 'Contrat de travail et droit commun', 'Le contrat de travail est soumis aux règles du droit commun. Il peut être établi selon les formes que les parties contractantes décident d’adopter.'),
  A('trav', 'L. 1221-19', 'Durée de la période d’essai', 'Le contrat de travail à durée indéterminée peut comporter une période d’essai dont la durée maximale est : 1° Pour les ouvriers et les employés, de deux mois ; 2° Pour les agents de maîtrise et les techniciens, de trois mois ; 3° Pour les cadres, de quatre mois. Elle peut être renouvelée une fois si un accord de branche étendu le prévoit.', true),
  A('trav', 'L. 1231-1', 'Modes de rupture du CDI', 'Le contrat de travail à durée indéterminée peut être rompu à l’initiative de l’employeur ou du salarié, ou d’un commun accord, dans les conditions prévues par les dispositions du présent titre. Ces dispositions ne sont pas applicables pendant la période d’essai.'),
  A('trav', 'L. 1232-1', 'Cause réelle et sérieuse', 'Tout licenciement pour motif personnel est motivé dans les conditions définies par le présent chapitre. Il est justifié par une cause réelle et sérieuse.'),
  A('trav', 'L. 1233-3', 'Motif économique de licenciement', 'Constitue un licenciement pour motif économique le licenciement effectué par un employeur pour un ou plusieurs motifs non inhérents à la personne du salarié résultant d’une suppression ou transformation d’emploi ou d’une modification, refusée par le salarié, d’un élément essentiel du contrat de travail, consécutives notamment à des difficultés économiques (caractérisées par l’évolution significative d’au moins un indicateur, comme une baisse des commandes ou du chiffre d’affaires), à des mutations technologiques, à une réorganisation nécessaire à la sauvegarde de la compétitivité ou à la cessation d’activité de l’entreprise.', true),
  A('trav', 'L. 1235-3', 'Barème d’indemnisation du licenciement injustifié', 'Si le licenciement d’un salarié survient pour une cause qui n’est pas réelle et sérieuse, le juge peut proposer la réintégration ; à défaut, il octroie au salarié une indemnité à la charge de l’employeur, dont le montant est compris entre des montants minimaux et maximaux fixés par un barème selon l’ancienneté (ordonnance du 22 septembre 2017). Le barème est écarté en cas de nullité du licenciement (harcèlement, discrimination, violation d’une liberté fondamentale…).', true),
  A('trav', 'L. 1237-11', 'Rupture conventionnelle', 'L’employeur et le salarié peuvent convenir en commun des conditions de la rupture du contrat de travail qui les lie. La rupture conventionnelle, exclusive du licenciement ou de la démission, ne peut être imposée par l’une ou l’autre des parties. Elle résulte d’une convention signée par les parties au contrat. Elle est soumise aux dispositions de la présente section destinées à garantir la liberté du consentement des parties.'),
  A('trav', 'L. 1242-1', 'Interdiction de pourvoir durablement un emploi permanent par CDD', 'Un contrat de travail à durée déterminée, quel que soit son motif, ne peut avoir ni pour objet ni pour effet de pourvoir durablement un emploi lié à l’activité normale et permanente de l’entreprise.'),
  A('trav', 'L. 1471-1', 'Prescription des actions relatives au contrat de travail', 'Toute action portant sur l’exécution du contrat de travail se prescrit par deux ans à compter du jour où celui qui l’exerce a connu ou aurait dû connaître les faits lui permettant d’exercer son droit. Toute action portant sur la rupture du contrat de travail se prescrit par douze mois à compter de la notification de la rupture. (Exceptions : salaires, discrimination, harcèlement, dommage corporel.)', true),
  A('trav', 'L. 2511-1', 'Exercice du droit de grève', 'L’exercice du droit de grève ne peut justifier la rupture du contrat de travail, sauf faute lourde imputable au salarié. Son exercice ne peut donner lieu de la part de l’employeur à des mesures discriminatoires en matière de rémunérations et d’avantages sociaux. Tout licenciement prononcé en absence de faute lourde est nul de plein droit.'),
  A('trav', 'L. 3121-27', 'Durée légale du travail', 'La durée légale de travail effectif des salariés à temps complet est fixée à trente-cinq heures par semaine.'),
  A('trav', 'L. 4121-1', 'Obligation de sécurité de l’employeur', 'L’employeur prend les mesures nécessaires pour assurer la sécurité et protéger la santé physique et mentale des travailleurs. Ces mesures comprennent des actions de prévention des risques professionnels, des actions d’information et de formation, et la mise en place d’une organisation et de moyens adaptés. L’employeur veille à l’adaptation de ces mesures pour tenir compte du changement des circonstances et tendre à l’amélioration des situations existantes.', true),

  // ===================== CJA / CRPA =====================
  A('cja', 'L. 211-1', 'Compétence des tribunaux administratifs', 'Les tribunaux administratifs sont, en premier ressort et sous réserve des compétences attribuées aux autres juridictions administratives, juges de droit commun du contentieux administratif. (Les alinéas suivants concernent les cours administratives d’appel et le Conseil d’État.)', true),
  A('cja', 'L. 521-1', 'Référé-suspension', 'Quand une décision administrative, même de rejet, fait l’objet d’une requête en annulation ou en réformation, le juge des référés, saisi d’une demande en ce sens, peut ordonner la suspension de l’exécution de cette décision, ou de certains de ses effets, lorsque l’urgence le justifie et qu’il est fait état d’un moyen propre à créer, en l’état de l’instruction, un doute sérieux quant à la légalité de la décision.', true),
  A('cja', 'L. 521-2', 'Référé-liberté', 'Saisi d’une demande en ce sens justifiée par l’urgence, le juge des référés peut ordonner toutes mesures nécessaires à la sauvegarde d’une liberté fondamentale à laquelle une personne morale de droit public ou un organisme de droit privé chargé de la gestion d’un service public aurait porté, dans l’exercice d’un de ses pouvoirs, une atteinte grave et manifestement illégale. Le juge des référés se prononce dans un délai de quarante-huit heures.'),
  A('cja', 'L. 521-3', 'Référé mesures utiles', 'En cas d’urgence et sur simple demande qui sera recevable même en l’absence de décision administrative préalable, le juge des référés peut ordonner toutes autres mesures utiles sans faire obstacle à l’exécution d’aucune décision administrative.'),
  A('cja', 'L. 911-1', 'Pouvoir d’injonction', 'Lorsque sa décision implique nécessairement qu’une personne morale de droit public ou un organisme de droit privé chargé de la gestion d’un service public prenne une mesure d’exécution dans un sens déterminé, la juridiction, saisie de conclusions en ce sens, prescrit cette mesure, assortie le cas échéant d’un délai d’exécution. Elle peut aussi l’assortir d’une astreinte.', true),
  A('cja', 'R. 421-1', 'Délai de recours contentieux', 'La juridiction ne peut être saisie que par voie de recours formé contre une décision, et ce, dans les deux mois à partir de la notification ou de la publication de la décision attaquée. Lorsque la requête tend au paiement d’une somme d’argent, elle n’est recevable qu’après l’intervention de la décision prise par l’administration sur une demande préalablement formée devant elle.', true),
  A('crpa', 'L. 121-1', 'Procédure contradictoire préalable', 'Exception faite des cas où il est statué sur une demande, les décisions individuelles qui doivent être motivées, ainsi que celles qui, bien que non mentionnées dans cette liste, sont prises en considération de la personne, sont soumises au respect d’une procédure contradictoire préalable.'),
  A('crpa', 'L. 211-2', 'Obligation de motivation', 'Les personnes physiques ou morales ont le droit d’être informées sans délai des motifs des décisions administratives individuelles défavorables qui les concernent. Doivent notamment être motivées les décisions qui restreignent l’exercice des libertés publiques ou constituent une mesure de police, infligent une sanction, retirent ou abrogent une décision créatrice de droits, opposent une prescription ou une forclusion, refusent un avantage dont l’attribution constitue un droit.', true),
  A('crpa', 'L. 231-1', 'Le silence vaut acceptation', 'Le silence gardé pendant deux mois par l’administration sur une demande vaut décision d’acceptation.'),
  A('crpa', 'L. 242-1', 'Retrait et abrogation des décisions créatrices de droits', 'L’administration ne peut abroger ou retirer une décision créatrice de droits de sa propre initiative ou sur la demande d’un tiers que si elle est illégale et si l’abrogation ou le retrait intervient dans le délai de quatre mois suivant la prise de cette décision.'),

  // ===================== CODE DE COMMERCE =====================
  A('com', 'L. 110-1', 'Actes de commerce par nature', 'La loi répute actes de commerce notamment : tout achat de biens meubles pour les revendre ; tout achat de biens immeubles aux fins de les revendre (sauf construction) ; toutes opérations d’intermédiaire pour l’achat, la souscription ou la vente d’immeubles, de fonds de commerce, d’actions ou parts de sociétés immobilières ; toute entreprise de location de meubles, de manufactures, de commission, de transport ; toute opération de change, banque, courtage ; toutes les opérations de banques publiques ; entre toutes personnes, les lettres de change.', true),
  A('com', 'L. 110-3', 'Liberté de la preuve entre commerçants', 'A l’égard des commerçants, les actes de commerce peuvent se prouver par tous moyens à moins qu’il n’en soit autrement disposé par la loi.'),
  A('com', 'L. 121-1', 'Définition du commerçant', 'Sont commerçants ceux qui exercent des actes de commerce et en font leur profession habituelle.'),
  A('com', 'L. 223-1', 'La SARL', 'La société à responsabilité limitée est instituée par une ou plusieurs personnes qui ne supportent les pertes qu’à concurrence de leurs apports. Lorsque la société ne comporte qu’une seule personne, celle-ci est dénommée « associé unique » (EURL). Le nombre d’associés ne peut être supérieur à cent.', true),
  A('com', 'L. 225-1', 'La société anonyme', 'La société anonyme est la société dont le capital est divisé en actions et qui est constituée entre deux associés ou plus. Les associés ne supportent les pertes qu’à concurrence de leurs apports. (Sept associés au moins pour une SA cotée.)', true),
  A('com', 'L. 227-1', 'La SAS', 'Une société par actions simplifiée peut être instituée par une ou plusieurs personnes qui ne supportent les pertes qu’à concurrence de leur apport. Lorsque cette société ne comporte qu’une seule personne, celle-ci est dénommée « associé unique » (SASU). Les statuts fixent librement l’organisation de la société, sous réserve de la désignation d’un président.', true),
  A('com', 'L. 442-1', 'Pratiques restrictives de concurrence', 'Engage la responsabilité de son auteur et l’oblige à réparer le préjudice causé le fait, dans le cadre de la négociation commerciale, de la conclusion ou de l’exécution d’un contrat, par toute personne exerçant des activités de production, de distribution ou de services, d’obtenir un avantage ne correspondant à aucune contrepartie ou manifestement disproportionné, ou de soumettre l’autre partie à des obligations créant un déséquilibre significatif. Engage aussi sa responsabilité la rupture brutale, même partielle, d’une relation commerciale établie, en l’absence d’un préavis écrit suffisant.', true),
  A('com', 'L. 631-1', 'Redressement judiciaire et cessation des paiements', 'Il est institué une procédure de redressement judiciaire ouverte à tout débiteur (commerçant, artisan, agriculteur, professionnel indépendant, personne morale de droit privé) qui, dans l’impossibilité de faire face au passif exigible avec son actif disponible, est en cessation des paiements. La procédure est destinée à permettre la poursuite de l’activité de l’entreprise, le maintien de l’emploi et l’apurement du passif.', true),

  // ===================== CODE DE LA CONSOMMATION =====================
  A('conso', 'liminaire', 'Définitions : consommateur et professionnel', 'Est consommateur toute personne physique qui agit à des fins qui n’entrent pas dans le cadre de son activité commerciale, industrielle, artisanale, libérale ou agricole. Est non-professionnel toute personne morale qui n’agit pas à des fins professionnelles. Est professionnel toute personne physique ou morale, publique ou privée, qui agit à des fins entrant dans le cadre de son activité commerciale, industrielle, artisanale, libérale ou agricole, y compris lorsqu’elle agit au nom ou pour le compte d’un autre professionnel.', true),
  A('conso', 'L. 212-1', 'Clauses abusives', 'Dans les contrats conclus entre professionnels et consommateurs, sont abusives les clauses qui ont pour objet ou pour effet de créer, au détriment du consommateur, un déséquilibre significatif entre les droits et obligations des parties au contrat. Ces clauses sont réputées non écrites. L’appréciation ne porte ni sur la définition de l’objet principal du contrat ni sur l’adéquation du prix, pour autant que les clauses soient rédigées de façon claire et compréhensible.', true),
  A('conso', 'L. 218-2', 'Prescription biennale', 'L’action des professionnels, pour les biens ou les services qu’ils fournissent aux consommateurs, se prescrit par deux ans.'),
  A('conso', 'L. 221-18', 'Droit de rétractation', 'Le consommateur dispose d’un délai de quatorze jours pour exercer son droit de rétractation d’un contrat conclu à distance ou hors établissement, sans avoir à motiver sa décision ni à supporter d’autres coûts que ceux prévus par la loi. Le délai court à compter de la conclusion du contrat pour les services et de la réception du bien pour les ventes.', true),
  A('conso', 'L. 217-3', 'Garantie légale de conformité', 'Le vendeur délivre un bien conforme au contrat ainsi qu’aux critères légaux de conformité. Il répond des défauts de conformité existant au moment de la délivrance du bien qui apparaissent dans un délai de deux ans à compter de celle-ci. Pendant ce délai, les défauts sont présumés exister au moment de la délivrance (vingt-quatre mois pour les biens neufs, douze mois pour les biens d’occasion).', true),
];
